/* ===============================================  MASTER MSR BUSBSY [6..6]  ================================================ */
typedef enum {                                  /*!< I2C0_MASTER_MSR_BUSBSY                                                    */
  I2C0_MASTER_MSR_BUSBSY_CLEARED       = 0,     /*!< CLEARED : The I2C bus is idle.                                            */
  I2C0_MASTER_MSR_BUSBSY_SET           = 1,     /*!< SET : 'This Status bit is set on a START or when SCL goes low.
                                                     It is cleared on a STOP, or when a SCL high bus busy timeout
                                                     occurs and SCL and SDA are both high. This status is cleared
                                                     when the ACTIVE bit is low. Note that the Controller State
                                                     Machine will wait until this bit is cleared before starting
                                                     an I2C transaction. When first enabling the Controller
                                                     in multi Controller environments, FW should wait for one
                                                     I2C clock period after setting ACTIVE high before writing
                                                     to the MTCR register to start the transaction so that if
                                                     SCL goes low it will trigger the BUSBSY.                                  */
} I2C0_MASTER_MSR_BUSBSY_Enum;

