typedef enum {                                  /*!< TIMG0_COUNTERREGS_CCCTL_01_CCUPD                                          */
  TIMG0_COUNTERREGS_CCCTL_01_CCUPD_IMMEDIATELY = 0,/*!< IMMEDIATELY : Writes to the CCx_y register is written to the
                                                     register directly and has immediate effect.                               */
  TIMG0_COUNTERREGS_CCCTL_01_CCUPD_ZERO_EVT = 1,/*!< ZERO_EVT : Following a zero event (CTR=0) Writes to the CCx_y
                                                     register are stored in shadow register and transferred
                                                     to CCx_y in the TIMCLK cycle following CTR equals 0.                      */
  TIMG0_COUNTERREGS_CCCTL_01_CCUPD_COMPARE_DOWN_EVT = 2,/*!< COMPARE_DOWN_EVT : Following a CCD event (CTR=CC_xy) Writes
                                                     to the CCx_y register are stored in shadow register and
                                                     transferred to CCx_y in the TIMCLK cycle following CTR
                                                     equals the CCx_y register value.                                          */
  TIMG0_COUNTERREGS_CCCTL_01_CCUPD_COMPARE_UP_EVT = 3,/*!< COMPARE_UP_EVT : Following a CCU event (CTR=CC_xy) Writes to
                                                     the CCx_y register are stored in shadow register and transferred
                                                     to CCx_y in the TIMCLK cycle following CTR equals the CCx_y
                                                     register value.                                                           */
  TIMG0_COUNTERREGS_CCCTL_01_CCUPD_ZERO_LOAD_EVT = 4,/*!< ZERO_LOAD_EVT : Following a zero event(CTR=0) or load event
                                                     (CTR=LOAD) Writes to the CCx_y register are stored in shadow
                                                     register and transferred to ECCx_y in the TIMCLK cycle
                                                     following CTR equals 0 or CTR. Equals LD. Note this update
                                                     mechanism is defined for use only in configurations using
                                                     up/down counting. This mode is not intended for use in
                                                     down count configurations.                                                */
  TIMG0_COUNTERREGS_CCCTL_01_CCUPD_ZERO_RC_ZERO_EVT = 5,/*!< ZERO_RC_ZERO_EVT : Following a zero event (CTR=0) with repeat
                                                     count also zero (RC=0). Writes to the CCx_y register are
                                                     stored in shadow register and transferred to CCx_y in the
                                                     TIMCLK cycle following CTR equals 0 and if RC equal 0.                    */
  TIMG0_COUNTERREGS_CCCTL_01_CCUPD_TRIG = 6,    /*!< TRIG : Following a TRIG pulse. Writes to the CCx_y register
                                                     are stored in shadow register and transferred to CCx_y                    */
} TIMG0_COUNTERREGS_CCCTL_01_CCUPD_Enum;

