typedef enum {                                  /*!< I2C0_PDBGCTL_FREE                                                         */
  I2C0_PDBGCTL_FREE_STOP               = 0,     /*!< STOP : The peripheral freezes functionality while the Core Halted
                                                     input is asserted and resumes when it is deasserted.                      */
  I2C0_PDBGCTL_FREE_RUN                = 1,     /*!< RUN : The peripheral ignores the state of the Core Halted input           */
} I2C0_PDBGCTL_FREE_Enum;

/* ===============================================  I2C0 PDBGCTL SOFT [1..1]  ================================================ */
typedef enum {                                  /*!< I2C0_PDBGCTL_SOFT                                                         */
  I2C0_PDBGCTL_SOFT_IMMEDIATE          = 0,     /*!< IMMEDIATE : The peripheral will halt immediately, even if the
                                                     resultant state will result in corruption if the system
                                                     is restarted                                                              */
  I2C0_PDBGCTL_SOFT_DELAYED            = 1,     /*!< DELAYED : The peripheral blocks the debug freeze until it has
                                                     reached a boundary where it can resume without corruption                 */
} I2C0_PDBGCTL_SOFT_Enum;

