typedef enum {                                  /*!< UART0_RXDATA_FRMERR                                                       */
  UART0_RXDATA_FRMERR_CLR              = 0,     /*!< CLR : No framing error has occurred                                       */
  UART0_RXDATA_FRMERR_SET              = 1,     /*!< SET : The received character does not have a valid stop bit
                                                     sequence, which is one or two stop bits depending on the
                                                     UARTLCRH.STP2 setting (a valid stop bit is 1).                            */
} UART0_RXDATA_FRMERR_Enum;

/* ==============================================  UART0 RXDATA PARERR [9..9]  =============================================== */
typedef enum {                                  /*!< UART0_RXDATA_PARERR                                                       */
  UART0_RXDATA_PARERR_CLR              = 0,     /*!< CLR : No parity error has occurred                                        */
  UART0_RXDATA_PARERR_SET              = 1,     /*!< SET : The parity of the received data character does not match
                                                     the parity defined by bits 2 and 7 of the UARTLCRH register.              */
} UART0_RXDATA_PARERR_Enum;

/* =============================================  UART0 RXDATA BRKERR [10..10]  ============================================== */
